/** Sections every authoring task needs — the no-arg tool call inlines these. */
export const CORE_GUIDE_SECTIONS: readonly string[] = ['lifecycle', 'publish-requirements'];

/** Names of the sections whose `appliesTo` covers the given content type. */
export function guideSectionNamesFor(type: string): string[] {
  return GUIDE_SECTIONS.filter((s) => s.appliesTo === 'all' || s.appliesTo.includes(type)).map(
    (s) => s.name,
  );
}

/**
 * The full guide as one document — what guide-facts.spec.ts pins its claims
 * against, and the single source the tool's slices are composed from.
 */
export const AUTHORING_GUIDE = `# Authoring Usertour content\n\n${GUIDE_SECTIONS.map(
  (s) => `## ${s.title}\n${s.body}`,
).join('\n\n')}\n`;
